shortcuts.codeOnPrepare:
const raw = getVariable('shared_link').trim();
const m = raw.match(/https?:\/\/[^\s"'<>]+/);
const url = m ? m[0] : raw;
if (!/bilibili\.com|b23\.tv/i.test(url)) {
  showToast('未识别到 B站链接，请从 B站 App 分享视频或主页');
  abort();
}
setVariable('shared_link', url);
const r = showDialog('识别到：B站\n类型：bilibili\n链接：' + url + '\n\n确认加入订阅队列？', '提交订阅', {buttons: ['确认', '取消']});
if (r.result !== 'button1') {
  abort();
}

